import XCTest
import AVFoundation
import PrismCore
import UIKit
import UniformTypeIdentifiers
@testable import TogetherPoC

final class AudioSubtitleTests:XCTestCase {
 @MainActor func testSubtitlePickerOnlyDeliversOneSelection() {
  var selected:[URL]=[];var cancelled=0
  let picker=SubtitleDocumentPicker(onPick:{selected.append($0)},onCancel:{cancelled += 1})
  let coordinator=picker.makeCoordinator()
  let controller=UIDocumentPickerViewController(forOpeningContentTypes:[.data],asCopy:true)
  let url=URL(fileURLWithPath:"/tmp/subtitle.SRT")
  coordinator.documentPicker(controller,didPickDocumentsAt:[url])
  coordinator.documentPicker(controller,didPickDocumentsAt:[url])
  coordinator.documentPickerWasCancelled(controller)
  XCTAssertEqual(selected,[url]);XCTAssertEqual(cancelled,0)
 }

 @MainActor func testMKVRemuxExposesEmbeddedAudioAndSubtitleGroups() async throws {
  let url=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString+".mkv")
  try Data(base64Encoded:"")!.write(to:url)
  defer {try? FileManager.default.removeItem(at:url)}
  let remux=MKVRemux();let playlist=try await remux.prepare(url,headers:[:])
  let asset=AVURLAsset(url:playlist)
  let audio=try await asset.loadMediaSelectionGroup(for:.audible)
  let subtitles=try await asset.loadMediaSelectionGroup(for:.legible)
  XCTAssertEqual(audio?.options.count,1)
  XCTAssertEqual(subtitles?.options.count,1,"Embedded SRT must survive remux and reach AVPlayer")
  XCTAssertTrue(remux.audioTrackSummary.joined().contains("AAC"))
  XCTAssertTrue(remux.audioTrackSummary.joined().contains("1.0"))
  let model=TestClient(compatibilityPreparation:{_,_ in playlist},automaticallyConnect:false)
  let timeline:[String:Any]=["state":"paused","position":0,"updatedAt":0,"playbackRate":1]
  model.receive(["type":"WELCOME","room":["roomId":"embedded-tracks-test","hostId":"fixture-host","mediaUrl":"https://example.org/movie.mp4","version":1,"executeAt":0,"state":"paused","position":0,"updatedAt":0,"playbackRate":1,"before":timeline]],t4:0)
  model.beginLocalFileSelection();model.useLocalFile(url)
  for _ in 0..<100 {
   if model.audioLabels.count==1 && model.subtitleLabels.count==1 {break}
   try await Task.sleep(nanoseconds:100_000_000)
  }
  XCTAssertEqual(model.audioLabels.count,1,"Actual app must discover the audible selection group")
  XCTAssertEqual(model.subtitleLabels.count,1,"Actual app must discover the embedded subtitle group")
  model.chooseSubtitle(0)
  let item=try XCTUnwrap(model.adapter.player.currentItem)
  let loadedGroup=try await item.asset.loadMediaSelectionGroup(for:.legible)
  let group=try XCTUnwrap(loadedGroup)
  XCTAssertTrue(item.currentMediaSelection.selectedMediaOption(in:group) === group.options.first)
  model.chooseSubtitle(-2)
  XCTAssertNil(item.currentMediaSelection.selectedMediaOption(in:group))
  model.chooseAudio(0);XCTAssertEqual(model.selectedAudioIndex,0)
  let (masterData,_)=try await URLSession.shared.data(from:playlist)
  let master=try XCTUnwrap(String(data:masterData,encoding:.utf8))
  let subtitleLine=try XCTUnwrap(master.split(separator:"\n").first {$0.contains("TYPE=SUBTITLES")})
  let uriStart=try XCTUnwrap(subtitleLine.range(of:"URI=\""))
  let subtitleURI=String(subtitleLine[uriStart.upperBound...].prefix(while:{$0 != "\""}))
  let subtitlePlaylist=try XCTUnwrap(URL(string:subtitleURI,relativeTo:playlist)?.absoluteURL)
  let (listData,_)=try await URLSession.shared.data(from:subtitlePlaylist)
  let list=try XCTUnwrap(String(data:listData,encoding:.utf8))
  let segment=try XCTUnwrap(list.split(separator:"\n").first {!$0.hasPrefix("#")})
  let subtitleSegment=try XCTUnwrap(URL(string:String(segment),relativeTo:subtitlePlaylist)?.absoluteURL)
  let (cueData,_)=try await URLSession.shared.data(from:subtitleSegment)
  let cues=try XCTUnwrap(String(data:cueData,encoding:.utf8))
  XCTAssertTrue(cues.contains("WEBVTT"))
  XCTAssertTrue(cues.contains("Embedded subtitle test"),"The original subtitle content must reach the player, not just a menu label")
  let captionItem=AVPlayerItem(asset:asset)
  let captionPlayer=AVPlayer(playerItem:captionItem)
  let captions=ExternalSubtitles(player:captionPlayer)
  captions.attachNativeOutput(to:captionItem)
  captionItem.select(group.options.first,in:group)
  captionPlayer.play()
  for _ in 0..<100 {
   if captions.text.contains("Embedded subtitle test") {break}
   try await Task.sleep(nanoseconds:20_000_000)
  }
  XCTAssertTrue(captions.text.contains("Embedded subtitle test"),"The adjustable native subtitle layer must actually receive and display source text")
  captions.delay=10;XCTAssertEqual(captions.text,"")
  captions.delay = -0.1
  XCTAssertTrue(captions.text.contains("Embedded subtitle test"))
  captionPlayer.pause()
  remux.stop()
 }
 func testEmptyOptionSubtypeUsesUnambiguousTrackFormats() {
  let track=AudioTrackDetail(language:"eng",codecs:["mp4a"],channels:2)
  XCTAssertEqual(AudioTrackDetail.label(name:"English",index:0,language:"en-US",subtypes:[],tracks:[track],optionCount:2),"English [AAC · 2声道]")
  XCTAssertEqual(AudioTrackDetail.label(name:"English",index:0,language:nil,subtypes:[],tracks:[track],optionCount:1),"English [AAC · 2声道]")
 }
 func testConflictingTrackFormatsDoNotMislabelAudioOrClaimAtmos() {
  let tracks=[AudioTrackDetail(language:"en",codecs:["mp4a"],channels:2),AudioTrackDetail(language:"eng",codecs:["ec-3"],channels:6)]
  XCTAssertEqual(AudioTrackDetail.label(name:"English",index:1,language:"en",subtypes:[],tracks:tracks,optionCount:2),"English · 音轨 2")
  XCTAssertEqual(AudioTrackDetail.label(name:"English",index:0,language:"en",subtypes:["ec-3"],tracks:tracks,optionCount:2),"English [Dolby Digital Plus]")
 }
 @MainActor func testCopiedUppercaseSRTImportLoadsCuesAndInvalidFilePreservesPreviousSubtitle() async throws {
  let url=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString+".SRT")
  defer {try? FileManager.default.removeItem(at:url)}
  try Data("1\n00:00:00,000 --> 00:00:03,000\n字幕测试\n".utf8).write(to:url)
  let subtitles=ExternalSubtitles(player:AVPlayer());let loaded=await subtitles.importFile(url)
  XCTAssertTrue(loaded);XCTAssertTrue(subtitles.enabled);XCTAssertEqual(subtitles.status,"已加载1条字幕")
  try Data("not a subtitle".utf8).write(to:url)
  let invalid=await subtitles.importFile(url);XCTAssertFalse(invalid);XCTAssertTrue(subtitles.available)
  XCTAssertTrue(subtitles.status.contains("读取失败"))
 }
}
